/**
 * Feedback Expander AMD module.
 *
 * Adds an "Edit in editor" button next to every feedback input on the
 * Gradebook Single View page. Clicking it opens a Moodle modal with a TinyMCE
 * editor (or a plain-textarea fallback). "Insert and close" writes the content
 * back to the original input and, for activity grade items, ticks the
 * override checkbox so the value is actually submitted.
 *
 * Single View stores feedback as FORMAT_MOODLE, which renders the HTML the
 * editor produces; there is no format field to set.
 *
 * @module     local_feedbackexpander/expander
 * @copyright  2026 Tobias Sanders
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define("local_feedbackexpander/expander", [
    'core/modal_save_cancel',
    'core/modal_events',
    'core/str',
    'core/templates',
    'core/notification'
], function(ModalSaveCancel, ModalEvents, Str, Templates, Notification) {

    'use strict';

    /** Counter to generate unique textarea IDs inside each modal. */
    var instanceCounter = 0;

    /**
     * Find the override checkbox that belongs to a feedback input.
     *
     * Single View names every field "<type>_<gradeitemid>_<userid>", so
     * "feedback_12_34" pairs with "override_12_34". Manual grade items have
     * no override checkbox.
     *
     * @param {HTMLElement} feedbackInput
     * @returns {HTMLInputElement|null}
     */
    function findOverrideCheckbox(feedbackInput) {
        var name = feedbackInput.getAttribute('name') || '';
        var overrideName = name.replace(/^feedback_/, 'override_');
        if (overrideName === name) {
            return null;
        }
        return document.querySelector('input[type="checkbox"][name="' + CSS.escape(overrideName) + '"]');
    }

    /**
     * Return all feedback inputs in the DOM that can be edited and have no
     * button yet.
     *
     * A disabled input is only editable through its override checkbox; one
     * without such a checkbox, or with a disabled one (locked grade), is left
     * alone, because nothing typed into it would ever be submitted.
     *
     * @returns {HTMLElement[]}
     */
    function getFeedbackInputs() {
        // :not([data-feedbackexpander-attached]) is the primary deduplication guard.
        // We mark every processed input with this attribute immediately (before the
        // async string fetch), so repeated observer calls can never add a second icon.
        var inputs = Array.prototype.slice.call(
            document.querySelectorAll(
                'input[type="text"][name^="feedback_"]:not([data-feedbackexpander-attached]),' +
                'textarea[name^="feedback_"]:not([data-feedbackexpander-attached])'
            )
        );
        return inputs.filter(function(el) {
            // Exclude anything inside a Bootstrap modal (.modal element).
            if (el.closest('.modal') || el.readOnly) {
                return false;
            }
            if (el.disabled) {
                var override = findOverrideCheckbox(el);
                return !!override && !override.disabled;
            }
            return true;
        });
    }

    // ---------------------------------------------------------------------------
    // TinyMCE helpers
    // ---------------------------------------------------------------------------

    /**
     * Initialise TinyMCE on the textarea identified by textareaId.
     *
     * editor_tiny/loader is core's way to obtain the TinyMCE library on a page
     * that has no editor field of its own. If it is unavailable the plain
     * textarea remains functional.
     *
     * @param {string} textareaId
     * @param {string} initialContent
     */
    function initEditor(textareaId, initialContent) {
        require(['editor_tiny/loader'], function(loader) {
            loader.getTinyMCE().then(function(tinyMCE) {
                // Small delay: let any modal CSS transition finish before TinyMCE
                // measures the target element's dimensions.
                setTimeout(function() {
                    tinyMCE.init(buildTinyConfig(textareaId, initialContent, loader.baseUrl));
                }, 50);
                return tinyMCE;
            }).catch(Notification.exception);
        }, function() {
            // No TinyMCE on this site: the plain textarea stays usable.
        });
    }

    /**
     * Build the tinyMCE.init() config object.
     *
     * @param {string} textareaId
     * @param {string} initialContent
     * @param {string} baseUrl where core serves TinyMCE's skins and plugins from
     * @returns {object}
     */
    function buildTinyConfig(textareaId, initialContent, baseUrl) {
        var config = {
            target: document.getElementById(textareaId),
            // Moodle ships TinyMCE under the GPL; without this TinyMCE 7 shows a licence notice.
            // eslint-disable-next-line camelcase
            license_key: 'gpl',
            plugins: 'lists link',
            toolbar: 'undo redo | bold italic underline | bullist numlist | link',
            menubar: false,
            statusbar: false,
            height: 400,
            promotion: false,
            branding: false,
            setup: function(editor) {
                editor.on('init', function() {
                    editor.setContent(initialContent);
                });
            }
        };
        if (baseUrl) {
            // eslint-disable-next-line camelcase
            config.base_url = baseUrl;
        }
        return config;
    }

    /**
     * Retrieve the active TinyMCE editor instance for a given textarea ID.
     *
     * @param {string} textareaId
     * @returns {object|null}
     */
    function getEditorInstance(textareaId) {
        if (typeof window.tinyMCE !== 'undefined') {
            return window.tinyMCE.get(textareaId) || null;
        }
        return null;
    }

    /**
     * Read the full HTML content from TinyMCE, or fall back to the textarea value.
     *
     * @param {string} textareaId
     * @returns {string}  HTML string
     */
    function getEditorContent(textareaId) {
        var editor = getEditorInstance(textareaId);
        if (editor) {
            return editor.getContent(); // returns HTML
        }
        var textarea = document.getElementById(textareaId);
        return textarea ? textarea.value : '';
    }

    /**
     * Destroy the TinyMCE instance to prevent memory leaks.
     *
     * @param {string} textareaId
     */
    function destroyEditor(textareaId) {
        var editor = getEditorInstance(textareaId);
        if (editor) {
            editor.remove();
        }
    }

    // ---------------------------------------------------------------------------
    // Override-checkbox helper
    // ---------------------------------------------------------------------------

    /**
     * Tick the override checkbox of a feedback input, if it has one.
     *
     * Single View's own change handler then enables the feedback input; a
     * disabled input would not be submitted with the form.
     *
     * @param {HTMLElement} feedbackInput
     */
    function activateOverrideCheckbox(feedbackInput) {
        var cb = findOverrideCheckbox(feedbackInput);
        if (cb && !cb.checked && !cb.disabled) {
            cb.checked = true;
            cb.dispatchEvent(new Event('change', {bubbles: true}));
        }
    }

    // ---------------------------------------------------------------------------
    // Icon insertion
    // ---------------------------------------------------------------------------

    /**
     * Insert the trigger button immediately after the given input field.
     *
     * @param {HTMLElement} inputField
     * @param {string}      label  - localised button text
     */
    function insertTriggerIcon(inputField, label) {
        var trigger = document.createElement('button');
        trigger.type = 'button';
        trigger.className = 'feedbackexpander-trigger btn btn-sm btn-secondary';
        trigger.textContent = label;

        trigger.addEventListener('click', function() {
            openModal(inputField, trigger);
        });

        inputField.parentNode.insertBefore(trigger, inputField.nextSibling);
    }

    // ---------------------------------------------------------------------------
    // Modal
    // ---------------------------------------------------------------------------

    /**
     * Build and open the feedback editor modal for the given input field.
     *
     * @param {HTMLElement} targetInput   - the original feedback input
     * @param {HTMLElement} triggerEl     - the button that was clicked (for focus restoration)
     */
    function openModal(targetInput, triggerEl) {
        instanceCounter++;
        var textareaId = 'feedbackexpander-editor-' + instanceCounter;
        var currentValue = targetInput.value || '';

        // Fetch localised strings in parallel with template rendering.
        var stringsPromise = Str.getStrings([
            {key: 'editfeedback',  component: 'local_feedbackexpander'},
            {key: 'saveandclose',  component: 'local_feedbackexpander'},
            {key: 'close',         component: 'local_feedbackexpander'}
        ]);

        var bodyPromise = Templates.render('local_feedbackexpander/modal_body', {
            textareaid: textareaId,
            currentvalue: currentValue
        });

        Promise.all([stringsPromise, bodyPromise]).then(function(results) {
            var strings = results[0];

            return ModalSaveCancel.create({
                title: strings[0],   // 'editfeedback'
                body: results[1],
                large: true,
                // Without this every opened modal stays hidden in the DOM.
                removeOnClose: true,
                buttons: {
                    save: strings[1],    // 'saveandclose'
                    cancel: strings[2]   // 'close'
                }
            }).then(function(modal) {
                // Apply our custom CSS class so styles.css selectors work.
                modal.getRoot().addClass('feedbackexpander-modal');

                // Initialise TinyMCE after the modal is fully visible.
                modal.getRoot().on(ModalEvents.shown, function() {
                    initEditor(textareaId, currentValue);
                });

                // Save: read content → write to original input → close.
                modal.getRoot().on(ModalEvents.save, function(e) {
                    e.preventDefault();

                    var content = getEditorContent(textareaId); // HTML
                    destroyEditor(textareaId);

                    // Override first: it enables the input, so the value below
                    // is actually submitted.
                    activateOverrideCheckbox(targetInput);

                    targetInput.value = content;
                    // Notify Moodle (and any React/Vue wrappers) that the value changed.
                    targetInput.dispatchEvent(new Event('change', {bubbles: true}));
                    targetInput.dispatchEvent(new Event('input',  {bubbles: true}));

                    modal.hide();
                });

                // Cancel / hidden: destroy editor, restore focus.
                modal.getRoot().on(ModalEvents.hidden, function() {
                    destroyEditor(textareaId);
                    if (triggerEl) {
                        triggerEl.focus();
                    }
                });

                modal.show();
                return modal;
            });
        }).catch(Notification.exception);
    }

    // ---------------------------------------------------------------------------
    // Attaching icons
    // ---------------------------------------------------------------------------

    /**
     * Find all undecorated feedback inputs and attach trigger buttons.
     */
    function attachExpanderIcons() {
        var inputs = getFeedbackInputs();
        if (inputs.length === 0) {
            return;
        }

        // Mark inputs immediately – before the async string fetch – so that
        // any observer callback firing in the meantime finds them already
        // stamped and skips them.
        inputs.forEach(function(input) {
            input.setAttribute('data-feedbackexpander-attached', '1');
        });

        Str.getString('editfeedback', 'local_feedbackexpander').then(function(label) {
            inputs.forEach(function(input) {
                insertTriggerIcon(input, label);
            });
            return label;
        }).catch(Notification.exception);
    }

    // ---------------------------------------------------------------------------
    // MutationObserver (handles AJAX-driven user/item switches in Single View)
    // ---------------------------------------------------------------------------

    var observerAttached = false;
    var debounceTimer = null;

    /**
     * Watch the report for re-rendered rows and decorate their inputs.
     */
    function setupObserver() {
        if (observerAttached) {
            return;
        }
        observerAttached = true;

        var root = document.querySelector('.grade-report-singleview') || document.body;
        var observer = new MutationObserver(function() {
            // Debounce: wait until the DOM settles before scanning for new inputs.
            // This prevents a flood of calls when TinyMCE or our own code makes
            // several rapid DOM changes in a row.
            clearTimeout(debounceTimer);
            debounceTimer = setTimeout(attachExpanderIcons, 200);
        });
        observer.observe(root, {childList: true, subtree: true});
    }

    // ---------------------------------------------------------------------------
    // Public API
    // ---------------------------------------------------------------------------

    return {
        /**
         * Entry point called from the footer hook via $PAGE->requires->js_call_amd().
         */
        init: function() {
            // Run immediately in case the DOM is already ready.
            attachExpanderIcons();

            // Also observe for dynamically loaded content (AJAX navigation).
            setupObserver();
        }
    };
});
